import numpy as np
def sigmoid(z): return 1 / (1 + np.exp(-z))
rng = np.random.default_rng(1)
theta, ref_logits, beta, w, l = rng.normal(size=6), rng.normal(size=6), 0.1, 1, 4
def logp(t): return t - np.log(np.exp(t).sum())
def dpo_loss(t):
    lp, lr = logp(t), logp(ref_logits)
    return -np.log(sigmoid(beta * ((lp[w] - lr[w]) - (lp[l] - lr[l]))))
def dpo_grad(t):
    lp, lr = logp(t), logp(ref_logits)
    p, h = np.exp(lp), beta * ((lp[w] - lr[w]) - (lp[l] - lr[l]))
    return -beta * sigmoid(-h) * ((np.eye(6)[w] - p) - (np.eye(6)[l] - p))
eps = 1e-6
fd = np.array([(dpo_loss(theta + eps * e) - dpo_loss(theta - eps * e)) / (2 * eps) for e in np.eye(6)])
print(np.abs(dpo_grad(theta) - fd).max() < 1e-8)   # True
